fn is_palindrome(text: Vec<char>) -> bool {
    let n = text.len();
    
    // Helper function to lowercase only ASCII uppercase letters
    fn to_ascii_lowercase(c: char) -> char {
        if c >= 'A' && c <= 'Z' {
            ((c as u8) + 32) as char
        } else {
            c
        }
    }
    
    // Check palindrome by comparing mirrored positions
    for i in 0..n / 2 {
        let left = to_ascii_lowercase(text[i]);
        let right = to_ascii_lowercase(text[n - 1 - i]);
        
        if left != right {
            return false;
        }
    }
    
    true
}